  "cin.tpl.aula.d": "You're the new kid in class!",
  "cin.tpl.aula.l1": "Class, we have a new student today!",
  "cin.tpl.aula.l2": "Hi... I'm new here.",
  "cin.tpl.aula.l3": "Hi! Sit next to me!",
  "cin.tpl.aula.l4": "I think I'm gonna like it here!",
  "cin.tpl.aula.n1": "First day at the new school...",
  "cin.tpl.bolo": "The Cake Is Gone!",
  "cin.tpl.bolo.d": "A delicious mystery in the kitchen.",
  "cin.tpl.bolo.l1": "All done! The birthday cake turned out perfect!",
  "cin.tpl.bolo.l2": "Huh... WHERE'S THE CAKE?!",
  "cin.tpl.bolo.l3": "It wasn't me! I was... uh... sleeping!",
  "cin.tpl.bolo.l4": "Hmm...",
  "cin.tpl.bolo.l5": "Has anyone seen a cake? It was delicious!",
  "cin.tpl.bolo.l6": "Hahaha!",
  "cin.tpl.bolo.n1": "In Grandma Gema's kitchen...",
  "cin.tpl.castelo": "The Enchanted Castle (3D)",
  "cin.tpl.castelo.d": "A 3D adventure with movie cameras.",
  "cin.tpl.castelo.l1": "Who dares enter my castle?",
  "cin.tpl.castelo.l2": "Your Majesty, we found your lost crown!",
  "cin.tpl.castelo.l3": "My crown! You are heroes!",
  "cin.tpl.chuva": "Soggy Picnic",
  "cin.tpl.chuva.d": "When it rains, we dance!",
  "cin.tpl.chuva.l1": "What a lovely day for a picnic!",
  "cin.tpl.chuva.l2": "Oh no... rain!",
  "cin.tpl.chuva.l3": "You know what goes with rain? DANCING!",
  "cin.tpl.chuva.l4": "Best picnic ever!",
  "cin.tpl.lua": "Moon Mission",
  "cin.tpl.lua.d": "A very sweet meeting in space.",
  "cin.tpl.lua.l1": "Moon landing: complete! Beep boop.",
  "cin.tpl.lua.l2": "They say there are aliens here...",
  "cin.tpl.lua.l3": "Hello, Earthlings! Want a cookie?",
  "cin.tpl.lua.l4": "...I LOVE cookies!",
  "cin.tpl.show": "Talent Show",
  "cin.tpl.show.d": "Stage fright? Friends help out!",
  "cin.tpl.show.l1": "And now... please welcome... SPARK!",
  "cin.tpl.show.l2": "I... forgot the lyrics!",
  "cin.tpl.show.l3": "What now?!",
  "cin.tpl.show.l4": "You can do it! Just dance!",
  "cin.tpl.show.l5": "What a show!",
  "cin.tpl.show.n1": "The Big Talent Show!",
